/** All services in display order (see service-index.ts). */
export const services: Service[] = serviceOrder.map((slug) => {
  const found = entries.find((s) => s.slug === slug);
  if (!found) throw new Error(`No content for service "${slug}" in services.ts`);
  return found;
});

export function getService(slug: ServiceSlug): Service {
  const found = services.find((s) => s.slug === slug);
  if (!found) throw new Error(`Unknown service "${slug}"`);
  return found;
}
